import ApiService from '../services/api';
import DocumentBasedCarbonAssessment from './DocumentBasedCarbonAssessment';
import { countPendingVerificationDocuments } from '../utils/documentAssessmentAggregation';
import documentService, {
  SUPPORTED_DOCUMENT_ACCEPT_MAP,
  SUPPORTED_DOCUMENT_TYPE_LABEL,
} from '../services/documentService';
import { HIDE_DOCUMENTS_SENSITIVE_INPUTS_UI, HIDE_ISO_14067_UI } from '../constants/uiVisibility';
import TabSectionNavLinks from './TabSectionNavLinks';
import { useUrlTabParam } from '../hooks/useUrlTabParam';
