import React from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Tabs,
  Typography,
  useMediaQuery,
} from '@mui/material';
import { useTheme } from '@mui/material/styles';
import TabSectionNavLinks from '../TabSectionNavLinks';
import {
  formatHighValueBillStatus,
  formatImportAmount,
  formatImportDate,
  formatSimilarityScore,
  getImportCategoryCount,
  pendingRowKey,
  type ImportDetailsTab,
  type LastAccountingImportResult,
  type PendingBillUpload,
} from './accountingImportResult';

interface AccountingImportDetailsProps {
  open: boolean;
  result: LastAccountingImportResult;
  tab: ImportDetailsTab;
  uploadingSourceId?: string | null;
  onClose: () => void;
  onTabChange: (tab: ImportDetailsTab) => void;
  onReviewBillRequired: () => void;
  onUploadBill: (pending: PendingBillUpload, file: File) => void;
}

const TAB_LABELS: Record<ImportDetailsTab, string> = {
  imported: 'Imported',
  billRequired: 'Bill required',
  duplicates: 'Duplicates',
  invalid: 'Invalid',
  failed: 'Failed',
};

const TAB_ORDER: ImportDetailsTab[] = [
  'imported',
  'billRequired',
  'duplicates',
  'invalid',
  'failed',
];

const EMPTY_COPY: Record<ImportDetailsTab, string> = {
  imported: 'No transactions were imported.',
  billRequired: 'No transactions require bill upload.',
  duplicates: 'No duplicate transactions were found in this import.',
  invalid: 'No invalid rows were detected.',
  failed: 'No transactions failed to save.',
};

const EmptyState: React.FC<{ message: string }> = ({ message }) => (
  <Box sx={{ textAlign: 'center', py: 4 }}>
    <Typography variant="body2" color="text.secondary">
      {message}
    </Typography>
  </Box>
);

const AccountingImportDetails: React.FC<AccountingImportDetailsProps> = ({
  open,
  result,
  tab,
  uploadingSourceId,
  onClose,
  onTabChange,
  onReviewBillRequired,
  onUploadBill,
}) => {
  const theme = useTheme();
  const fullScreen = useMediaQuery(theme.breakpoints.down('sm'));
  const tabIndex = TAB_ORDER.indexOf(tab);
  const tabLabels = TAB_ORDER.map((key) => `${TAB_LABELS[key]} (${getImportCategoryCount(result, key)})`);

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      fullScreen={fullScreen}
      aria-labelledby="accounting-import-details-title"
    >
      <DialogTitle id="accounting-import-details-title">
        Import details
        <Typography variant="body2" color="text.secondary">
          {result.fileName}
          {result.providerLabel ? ` · ${result.providerLabel}` : ''}
        </Typography>
      </DialogTitle>
      <DialogContent dividers>
        <Tabs
          value={tabIndex < 0 ? 0 : tabIndex}
          onChange={(_event, nextIndex: number) => {
            const next = TAB_ORDER[nextIndex];
            if (next) {
              onTabChange(next);
            }
          }}
          variant="scrollable"
          scrollButtons="auto"
          aria-label="Import result categories"
          sx={{ mb: 1 }}
        >
          {TAB_ORDER.map((key) => (
            <Tab
              key={key}
              id={`import-details-tab-${key}`}
              aria-controls={`import-details-panel-${key}`}
              label={`${TAB_LABELS[key]} (${getImportCategoryCount(result, key)})`}
            />
          ))}
        </Tabs>
        <TabSectionNavLinks
          tabLabels={tabLabels}
          currentIndex={tabIndex < 0 ? 0 : tabIndex}
          onNavigate={(index) => {
            const next = TAB_ORDER[index];
            if (next) {
              onTabChange(next);
            }
          }}
        />

        <Box
          role="tabpanel"
          id={`import-details-panel-${tab}`}
          aria-labelledby={`import-details-tab-${tab}`}
          sx={{ mt: 1 }}
        >
          {tab === 'imported' && (
            result.imported.length === 0 ? (
              <EmptyState message={EMPTY_COPY.imported} />
            ) : (
              <TableContainer>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Row</TableCell>
                      <TableCell>Source ID</TableCell>
                      <TableCell>Amount</TableCell>
                      <TableCell>Date</TableCell>
                      <TableCell>ID</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {result.imported.map((row, index) => (
                      <TableRow key={row.id || row.sourceId || `imported-${row.rowIndex ?? index}`}>
                        <TableCell>{row.rowIndex ?? '—'}</TableCell>
                        <TableCell>{row.sourceId || '—'}</TableCell>
                        <TableCell>{formatImportAmount(row.amount)}</TableCell>
                        <TableCell>{formatImportDate(row.date)}</TableCell>
                        <TableCell>{row.id || '—'}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            )
          )}

          {tab === 'billRequired' && (
            result.pendingBillUpload.length === 0 ? (
              <EmptyState message={EMPTY_COPY.billRequired} />
            ) : (
              <Stack spacing={1.5}>
                <Alert severity="warning">
                  These high-value transactions are pending a matching supporting bill. Matching is not proof the document is authentic.
                </Alert>
                <Button
                  variant="outlined"
                  color="warning"
                  onClick={onReviewBillRequired}
                  sx={{ alignSelf: { xs: 'stretch', sm: 'flex-start' } }}
                >
                  Open bill upload dialog
                </Button>
                {result.pendingBillUpload.map((pending) => {
                  const preview = pending.uploadRequest?.transactionPreview;
                  const sourceId = pending.sourceId || preview?.sourceId || `row-${pending.rowIndex}`;
                  const rowKey = pendingRowKey(pending);
                  const isUploading = uploadingSourceId === rowKey;
                  return (
                    <Box
                      key={rowKey}
                      sx={{ p: 1.5, border: '1px solid', borderColor: 'divider', borderRadius: 1 }}
                    >
                      <Typography variant="subtitle2">
                        {preview?.description || pending.description || `Row ${pending.rowIndex}`}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        {pending.transactionId ? `Transaction ${pending.transactionId} · ` : ''}
                        Row {pending.rowIndex}
                        {sourceId ? ` · ${sourceId}` : ''}
                        {` · ${formatImportAmount(preview?.amount ?? pending.amount)}`}
                        {` · ${preview?.category || pending.category || 'other'}`}
                      </Typography>
                      <Chip
                        size="small"
                        color={pending.billStatus === 'mismatch' ? 'error' : 'warning'}
                        label={formatHighValueBillStatus(pending.billStatus)}
                        sx={{ mt: 1 }}
                      />
                      {pending.actionRequired && pending.billStatus === 'awaiting_bill' && (
                        <Chip size="small" color="warning" label="Action required" sx={{ mt: 1, ml: 1 }} />
                      )}
                      {pending.uploadRequest?.userGuidance && (
                        <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                          {pending.uploadRequest.userGuidance}
                        </Typography>
                      )}
                      <Button
                        size="small"
                        variant="contained"
                        component="label"
                        disabled={isUploading}
                        sx={{ mt: 1 }}
                        startIcon={isUploading ? <CircularProgress size={14} color="inherit" /> : undefined}
                      >
                        Upload PDF bill
                        <input
                          hidden
                          type="file"
                          accept="application/pdf,.pdf"
                          onChange={(event) => {
                            const file = event.target.files?.[0];
                            event.target.value = '';
                            if (file) {
                              onUploadBill(pending, file);
                            }
                          }}
                        />
                      </Button>
                    </Box>
                  );
                })}
              </Stack>
            )
          )}

          {tab === 'duplicates' && (
            result.duplicates.length === 0 ? (
              <EmptyState message={EMPTY_COPY.duplicates} />
            ) : (
              <TableContainer>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Row</TableCell>
                      <TableCell>Source ID</TableCell>
                      <TableCell>Reasons</TableCell>
                      <TableCell>Similarity</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {result.duplicates.map((row, index) => (
                      <TableRow key={row.sourceId || `duplicate-${row.rowIndex ?? index}`}>
                        <TableCell>{row.rowIndex ?? '—'}</TableCell>
                        <TableCell>{row.sourceId || '—'}</TableCell>
                        <TableCell>
                          {Array.isArray(row.reasons) && row.reasons.length > 0
                            ? row.reasons.join('; ')
                            : '—'}
                        </TableCell>
                        <TableCell>{formatSimilarityScore(row.similarityScore)}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            )
          )}

          {tab === 'invalid' && (
            result.invalidRows.length === 0 ? (
              <EmptyState message={EMPTY_COPY.invalid} />
            ) : (
              <TableContainer>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Row</TableCell>
                      <TableCell>Source ID</TableCell>
                      <TableCell>Errors</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {result.invalidRows.map((row, index) => (
                      <TableRow key={row.sourceId || `invalid-${row.rowIndex ?? index}`}>
                        <TableCell>{row.rowIndex ?? '—'}</TableCell>
                        <TableCell>{row.sourceId || '—'}</TableCell>
                        <TableCell>
                          {Array.isArray(row.errors) && row.errors.length > 0
                            ? row.errors.join('; ')
                            : '—'}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            )
          )}

          {tab === 'failed' && (
            result.persistFailures.length === 0 ? (
              <EmptyState message={EMPTY_COPY.failed} />
            ) : (
              <TableContainer>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Row</TableCell>
                      <TableCell>Source ID</TableCell>
                      <TableCell>Status</TableCell>
                      <TableCell>Details</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {result.persistFailures.map((row, index) => (
                      <TableRow key={row.sourceId || `failed-${row.rowIndex ?? index}`}>
                        <TableCell>{row.rowIndex ?? '—'}</TableCell>
                        <TableCell>{row.sourceId || '—'}</TableCell>
                        <TableCell>Failed to save</TableCell>
                        <TableCell>{row.error || '—'}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            )
          )}
        </Box>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Close</Button>
      </DialogActions>
    </Dialog>
  );
};

export default AccountingImportDetails;
